-- Create the database, then select it before creating tables
CREATE DATABASE SchoolDB;
USE SchoolDB;

-- Create a table with a single-column primary key
CREATE TABLE Students (
  StudentID INT PRIMARY KEY,
  Name VARCHAR(50),
  Age INT
);

-- Parent table first: the one being referenced
CREATE TABLE Courses (
  CourseID INT PRIMARY KEY,
  CourseName VARCHAR(50)
);

-- Child table: CourseID here points at Courses
CREATE TABLE Students (
  StudentID INT PRIMARY KEY,
  Name VARCHAR(50),
  Age INT,
  CourseID INT,
  FOREIGN KEY (CourseID) REFERENCES Courses(CourseID)
);

-- Add a new column
ALTER TABLE Students ADD COLUMN Address VARCHAR(100);

-- Change the data type of an existing column
ALTER TABLE Students MODIFY COLUMN Class INT;

-- Remove a table completely
DROP TABLE Students;

-- Every column of every row
SELECT * FROM Students;

-- Only two columns
SELECT Name, Age FROM Students;

-- Rows that meet a condition
SELECT * FROM Students WHERE Age > 20;

-- Sorted by name, A to Z
SELECT * FROM Students ORDER BY Name ASC;

-- Delete one record
DELETE FROM Students WHERE ID = 1;

-- Delete every record matching a condition
DELETE FROM Students WHERE Age < 18;

-- Names starting with R
SELECT * FROM Students WHERE Name LIKE 'R%';

-- Names ending with n
SELECT * FROM Students WHERE Name LIKE '%n';

-- Names containing sh
SELECT * FROM Students WHERE Name LIKE '%sh%';

-- Names exactly four characters long
SELECT * FROM Students WHERE Name LIKE '____';

-- Name starts with R AND the student is in class 10
SELECT * FROM Students WHERE Name LIKE 'R%' AND Class = 10;

-- Name starts with R OR with S
SELECT * FROM Students WHERE Name LIKE 'R%' OR Name LIKE 'S%';

-- Name does NOT start with A
SELECT * FROM Students WHERE Name NOT LIKE 'A%';

-- Name contains a or e, but the student is not in class 9
SELECT * FROM Students
WHERE (Name LIKE '%a%' OR Name LIKE '%e%') AND NOT Class = 9;

-- Join two columns into one
SELECT CONCAT(Name, ' - ', Address) AS StudentInfo FROM Students;

-- How many characters in each name
SELECT Name, LENGTH(Name) AS NameLength FROM Students;

-- Upper case and lower case
SELECT UPPER(Name) AS UpperName FROM Students;
SELECT LOWER(Name) AS LowerName FROM Students;

-- How many students are there?
SELECT COUNT(*) FROM Students;

-- Total and average marks
SELECT SUM(Marks) FROM Students;
SELECT AVG(Marks) FROM Students;

-- Highest and lowest mark
SELECT MAX(Marks) FROM Students;
SELECT MIN(Marks) FROM Students;

